import math

def is_power_of_two(n):
    if n <= 0:
        return False
    return (n & (n - 1) == 0)

def check_case(x, n):
    lhs = x**n + x
    rhs_minus_2 = lhs - 2
    if rhs_minus_2 < 0:
        return None
    if is_power_of_two(rhs_minus_2):
        k = rhs_minus_2.bit_length() - 1
        return (x, n, k)
    return None

print("--- Case n=2 ---")
for x in range(3, 7): # Check x=3, 4, 5, 6
    solution = check_case(x, 2)
    if solution:
        print(f"Found solution for x={x}: {solution}")
    else:
        print(f"No solution for x={x}")

print("\n--- Case n=3 ---")
# Start from x = n+1 = 4
for x in range(4, 10): # Checking a few more values for n=3
    solution = check_case(x, 3)
    if solution:
        print(f"Found solution for x={x}: {solution}")
    else:
        print(f"No solution for x={x}")

